xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	uint64_t		total_bytes = 0;
	int			i;

	for (i = 0; i < nmaps; i++) {
		total_bytes += map[i].bm_length << btp->bt_metadata ?
			btp->bt_m_dalign : btp->bt_m_delalloc;
	}

	if (!xfs_buf_offset_ino(total_bytes)) {
		return NULL;
	}

	bp = xfs_buf_find_int(btp, map, nmaps, flags);

	if (bp && (bp->b_flags & XBF_STALE)) {
		if (!xfs_buf_lock_nowait(bp)) {
			xfs_buf_relse(bp);
			return NULL;
		}
	}

	if (!bp && new_bp) {
		xfs_buf_insert(new_bp, btp);
		return new_bp;
	}

	return bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg		*btp,
	struct xfs_buf_map		*map,
	int				nmaps,
	xfs_buf_flags_t			flags,
	xfs_buf_t			*new_bp)
{
	struct xfs_buf		*bp;
	uint64_t		num_bytes = 0;
	uint64_t		i;

	/*
	 * Calculate total number of bytes to be searched, ensuring alignment.
	 */
	for (i = 0; i < nmaps; i++) {
		num_bytes += map[i].bm_len;
	}

	/*
	 * Verify that the block number is within valid filesystem bounds.
	 */
	if (map[0].bm_bn < XFS_DADDR_TO_FSB_NULL(btp->bt_dev)) {
		return NULL;
	}

	/*
	 * Search the buffer cache for a matching buffer.
	 */
	bp = xfs_buf_find_in_tree(btp, map, nmaps);

	if (bp) {
		/*
		 * If a matching buffer is found, check if it is stale.
		 */
		if (xfs_buf_is_stale(bp)) {
			xfs_buf_lock(bp);
			if (xfs_buf_is_stale(bp)) {
				xfs_buf_stale(bp);
			}
		} else {
			xfs_buf_lock(bp);
		}
		return bp;
	}

	/*
	 * If no buffer is found, insert a new buffer into the tree.
	 */
	if (new_bp) {
		new_bp->b_buftarg = btp;
		new_bp->b_flags = flags;
		xfs_buf_insert_in_tree(new_bp);
		xfs_buf_lock(new_bp);
		return new_bp;
	}

	return NULL;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	uint64_t		first_block;
	uint64_t		last_block;
	int			i;

	/*
	 * Calculate the first and last block numbers for the buffer.
	 */
	first_block = map->bm_bn;
	last_block = first_block;

	for (i = 1; i < nmaps; i++) {
		if (map[i].bm_bn != last_block + 1)
			break;
		last_block = map[i].bm_bn;
	}

	/*
	 * Validate the block range to be within filesystem bounds.
	 */
	if (!xfs_sb_block_valid(&btp->bt_mount->m_sb, first_block,
				last_block - first_block + 1))
		return NULL;

	/*
	 * Search for an existing buffer matching the block range.
	 */
	bp = xfs_buf_find_list(btp, first_block, last_block - first_block + 1,
			       flags);

	/*
	 * If an existing buffer is found, check for staleness and attempt to lock.
	 */
	if (bp) {
		if (xfs_buf_isstale(bp))
			xfs_buf_stale(bp);
		if (!xfs_buf_lock(bp))
			goto out;
		return bp;
	}

	/*
	 * If no matching buffer is found, insert a new one.
	 */
	if (new_bp) {
		new_bp->b_bn = first_block;
		new_bp->b_count = last_block - first_block + 1;
		xfs_buf_insert(new_bp, btp);
		return new_bp;
	}

out:
	return NULL;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	uint64_t		bno = map[0].bm_bn;
	int			nblocks = 0;
	int			i;

	for (i = 0; i < nmaps; i++)
		nblocks += XFS_BUF_MAP_BLOCKS(&map[i]);

	/*
	 * Check for valid block numbers and alignment.
	 */
	if (!xfs_verify_alignment(btp, bno, nblocks))
		return NULL;

	/*
	 * Look up buffer in the cache.
	 */
	bp = xfs_buf_find_nowait(btp, bno, nblocks, flags, NULL);
	if (bp) {
		/*
		 * If the buffer is stale, we try to invalidate it.
		 */
		if (xfs_buf_is_stale(bp)) {
			xfs_buf_stale_unlock(bp);
			xfs_buf_rele(bp);
			bp = NULL;
		}
	}

	/*
	 * If no matching buffer is found, insert the new one.
	 */
	if (!bp && new_bp) {
		new_bp->b_bn = bno;
		new_bp->b_bno = bno;
		new_bp->b_count = nblocks;
		xfs_buf_insert(new_bp);
		bp = new_bp;
	}

	return bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	struct xfs_mount	*mp = btp->bt_mount;
	xfs_daddr_t		daddr;
	int			i;
	int			nblocks = 0;

	for (i = 0; i < nmaps; i++) {
		nblocks += map[i].bm_len;
	}

	ASSERT(nblocks > 0);

	daddr = map[0].bm_bn;

	if (mp->m_sb.sb_blocksize != XFS_BLOCK_SIZE(mp) && 
	    ((daddr % (XFS_BLOCK_SIZE(mp) / mp->m_sb.sb_blocksize)) != 0)) {
		return NULL;
	}

	if (daddr >= XFS_FSB_TO_BB(mp, mp->m_sb.sb_dblocks)) {
		return NULL;
	}

	bp = xfs_buf_find_by_bno(btp, daddr, nblocks);

	if (bp) {
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
		}
		if (xfs_buf_lock(bp, flags)) {
			xfs_buf_rele(bp);
			return NULL;
		}
		return bp;
	}

	if (new_bp) {
		new_bp->b_bn = daddr;
		new_bp->b_bno = daddr;
		new_bp->b_nblocks = nblocks;
		new_bp->b_buftarg = btp;
		new_bp->b_flags |= flags;

		xfs_buf_insert(new_bp);
		return new_bp;
	}

	return NULL;
}
